from pathlib import Path
import json
from playwright.sync_api import sync_playwright
ROOT=Path(__file__).resolve().parents[1];out=ROOT/'outputs'; assets=out/'demo_assets';report={'checks':{},'errors':[]}
with sync_playwright() as p:
    browser=p.chromium.launch(headless=True,executable_path='/usr/bin/chromium',args=['--no-sandbox','--disable-gpu']);page=browser.new_page(viewport={'width':1720,'height':1040},device_scale_factor=1);page.on('pageerror',lambda e:report['errors'].append(str(e)));page.goto('http://127.0.0.1:18765',wait_until='networkidle');page.wait_for_selector('#conversationTitle');report['checks']['boot']=True;page.screenshot(path=str(out/'product_before.png'),full_page=True);page.set_input_files('#fileInput',[str(assets/'boss_frame.png'),str(assets/'boss_replay.mp4'),str(assets/'battle.log')]);page.wait_for_function("document.querySelectorAll('#pendingAssets .pending-asset').length===3",timeout=30000);report['checks']['multimodal_upload']=True;report['pending_assets']=page.locator('#pendingAssets .pending-asset').count();page.fill('#messageInput','帮我复盘这场 Boss 战，重点看 1 分钟之后为什么会突然掉血，并给研发一个可执行的排查顺序。');page.click('#sendBtn');page.wait_for_function("document.querySelectorAll('#messageList .msg.assistant').length>=1",timeout=60000);report['checks']['chat_answer']=True;report['assistant_text']=page.locator('#messageList .msg.assistant').last.locator('.msg-content').inner_text()[:700];report['evidence_cards']=page.locator('#evidenceList .evidence-card').count();report['progress_rows']=page.locator('#progressList .progress-row').count();page.screenshot(path=str(out/'product_after.png'),full_page=True);page.click(".right-tab[data-panel='evidence']");page.screenshot(path=str(out/'product_evidence.png'),full_page=True);page.click('#providerBtn');page.wait_for_selector('#providerModal:not([hidden])');report['provider_cards']=page.locator('#providerGrid .provider-card').count();page.screenshot(path=str(out/'product_providers.png'),full_page=True);browser.close()
(out/'product_e2e.json').write_text(json.dumps(report,ensure_ascii=False,indent=2),encoding='utf-8');print(json.dumps(report,ensure_ascii=False,indent=2))
